css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 7px 12px; margin-bottom: 11px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 6px;}
.mz .ord-tabla{display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px;}
.mz .ord-tabla .oc{border: 1.5px solid var(--bosque); border-radius: 6px; text-align: center; font-size: 10px; font-weight: 700; padding: 3px 1px; line-height: 1.1;}
.mz .ord-tabla .oc b{display: block; font-size: 15px;}
.mz .ej-block:last-of-type{margin-bottom: 0;}
.mz .unir-grid{display: grid; grid-template-columns: 100px 1fr 180px; gap: 4px 0; align-items: center;}
.mz .unir-grid .u-cif{font-size: 19px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 5px 0;}
.mz .unir-grid .u-pal{font-size: 15px; font-weight: 600; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .unir-grid .u-mid{height: 8px;}
.mz .esc-fila{display: flex; align-items: center; gap: 12px; font-size: 17px; font-weight: 700; margin-bottom: 6px;}
.mz .esc-fila .pal{min-width: 150px;}
.mz .esc-fila .caja-cif{width: 80px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .serie-cajas{display: flex; gap: 4px; flex-wrap: nowrap; font-size: 16px; font-weight: 700;}
.mz .serie-cajas .caja-num{width: 50px; height: 42px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; flex: 1;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .pal-fila{display: flex; align-items: center; gap: 12px; font-size: 17px; font-weight: 700; margin-bottom: 6px;}
.mz .pal-fila .cif{min-width: 60px;}
.mz .pal-fila .caja-pal{flex: 1; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .oc{line-height: 1.725 !important;}
